use crate::{model::*,unit_support::*,wm063::*};
fn market(g:&mut Game)->String{let id=held(g,ID,0);fund(g,0,"WM057",8);act(g,0,Action{card_id:Some(id.clone()),target_id:Some("society:p0".into()),..Action::new("play")});crate::jc029_tests::pass_top(g);g.attachments.iter().find(|a|a.card.definition==ID).unwrap().card.id.clone()}
fn activate(g:&mut Game,actor:usize,id:&str,key:&str,cost:&str,target:Option<&str>){act(g,actor,Action{card_id:Some(id.into()),ability_id:Some(key.into()),cost_selected:Some(vec![cost.into()]),target_id:target.map(Into::into),..Action::new("activate")});}
#[test]fn wm063_draw_and_cost_types(){let mut g=game();let id=market(&mut g);let bad=held(&mut g,"JC001",0);reject(&mut g,0,Action{card_id:Some(id.clone()),ability_id:Some(DRAW.into()),cost_selected:Some(vec![bad]),..Action::new("activate")});let spell=held(&mut g,"JC102",0);let n=g.players[0].hand.len();activate(&mut g,0,&id,DRAW,&spell,None);crate::jc029_tests::pass_top(&mut g);assert_eq!(g.players[0].hand.len(),n);restore(&mut g);assert!(!crate::catalog::card(ID).supported);}
#[test]fn wm063_repress_chosen_player_and_restore(){let mut g=game();let id=market(&mut g);let cost=held(&mut g,"JC001",0);let team=g.team(1);g.regions[0].influence[team]=3;activate(&mut g,0,&id,REPRESS,&cost,None);crate::jc029_tests::pass_top(&mut g);choose(&mut g,vec!["p1".into()]);assert_eq!(g.pending.as_ref().unwrap().seat,1);assert_eq!(g.pending.as_ref().unwrap().choice.min,Some(2));restore(&mut g);let opts=g.pending.as_ref().unwrap().choice.options.iter().take(2).map(|o|o.id.clone()).collect();choose(&mut g,opts);assert_eq!(g.regions[0].influence[g.team(1)],1);}
#[test]fn wm063_borrow_permission_is_personal(){let mut g=game();let id=market(&mut g);fund(&mut g,2,"JC001",3);let spell=held(&mut g,"JC102",2);g.begin_window(Window::Action(1));let a=Action{card_id:Some(id.clone()),ability_id:Some(DRAW.into()),cost_selected:Some(vec![spell.clone()]),..Action::new("activate")};reject(&mut g,2,a.clone());g.players[2].society_zone.secrecy=1;assert!(g.legal_actions(2).iter().any(|v|v.action.card_id.as_deref()==Some(&id)));act(&mut g,2,a);g.players[2].society_zone.secrecy=0;restore(&mut g);crate::jc029_tests::pass_top(&mut g);assert!(!g.attachments.iter().find(|v|v.card.id==id).unwrap().card.exhausted);}
#[test]fn wm063_mark_and_damaged_payment_rejected(){let mut g=game();let id=market(&mut g);let cost=held(&mut g,"JC073",0);let target=field(&mut g,"JC001",1);activate(&mut g,0,&id,MARK,&cost,Some(&target));let mut bad=g.clone();if let PaidCost::WM063Discard{secrecy,..}=&mut bad.stack.last_mut().unwrap().frame.as_mut().unwrap().already_paid[1]{*secrecy=0;}bad.stack.last_mut().unwrap().frame.as_mut().unwrap().actor=1;assert!(Game::from_persisted(&serde_json::to_string(&bad).unwrap()).is_err());crate::jc029_tests::pass_top(&mut g);assert_eq!(g.board(&target).unwrap().1.permanent_combat_markers,1);restore(&mut g);}
#[test]fn wm063_repression_zero_one_self_and_corrupt_pending(){for count in 0..3{let mut g=game();let id=market(&mut g);let team=g.team(0);g.regions[0].influence[team]=count;let cost=held(&mut g,"JC001",0);activate(&mut g,0,&id,REPRESS,&cost,None);crate::jc029_tests::pass_top(&mut g);choose(&mut g,vec!["p0".into()]);if count>0{for mutation in 0..4{let mut bad=g.clone();let p=bad.pending.as_mut().unwrap();match mutation{0=>p.choice.min=Some(0),1=>p.seat=1,2=>if let ChoiceResolution::Frame{frame,..}=&mut p.resolution{frame.already_paid.clear();},_=>if let ChoiceResolution::Frame{frame,..}=&mut p.resolution{bad.effects.push_back(Effect::Frame{frame:frame.clone()});}}assert!(Game::from_persisted(&serde_json::to_string(&bad).unwrap()).is_err());let mut room=crate::jc029_tests::envelope(&g);room.game=bad;assert!(crate::room::RoomEnvelope::from_persisted(&serde_json::to_string(&room).unwrap()).is_err());}let ids=g.pending.as_ref().unwrap().choice.options.iter().take(count as usize).map(|o|o.id.clone()).collect();choose(&mut g,ids);}assert!(g.pending.is_none());assert_eq!(g.regions[0].influence[team],0);}}
#[test]fn wm063_target_changed_and_teammate_not_borrower(){let mut g=game();let id=market(&mut g);let target=field(&mut g,"JC001",1);let cost=held(&mut g,"JC073",0);activate(&mut g,0,&id,MARK,&cost,Some(&target));g.board_mut(&target).unwrap().face_down=true;crate::jc029_tests::pass_top(&mut g);assert_eq!(g.board(&target).unwrap().1.permanent_combat_markers,0);let seat=(1..4).find(|s|g.team(*s)==g.team(0)).unwrap();g.players[seat].society_zone.secrecy=1;let card=&g.attachments.iter().find(|a|a.card.id==id).unwrap().card;assert!(!g.wm063_borrow(seat,card));restore(&mut g);}
fn duplicates(mut v:serde_json::Value)->serde_json::Value{for s in v["steps"].as_array_mut().unwrap(){let r=crate::room::RoomEnvelope::from_persisted(s["expected"]["state"].as_str().unwrap()).unwrap();let d=r.transition(s["seat"].as_u64().unwrap()as usize,Some(serde_json::from_value(s["command"].clone()).unwrap()),0).unwrap();assert_eq!(d.state,s["expected"]["state"]);assert!(!d.changed&&d.journal.is_empty());s["duplicate"]=serde_json::to_value(d).unwrap();}v}
fn prepared(key:&str,index:usize)->serde_json::Value{use crate::abi112_review_play_tests::Trace;let mut g=game();let id=market(&mut g);let cost=held(&mut g,match key{DRAW=>"JC102",REPRESS=>"JC001",_=>"JC073"},2);fund(&mut g,2,"JC001",3);g.players[2].society_zone.secrecy=1;g.begin_window(Window::Action(1));let target=field(&mut g,"JC001",0);let team=g.team(0);g.regions[0].influence[team]=3;let mut t=Trace::new_preserving_rng(g,format!("wm063-prepared-borrow-{key}"),index);t.action(2,Action{card_id:Some(id),ability_id:Some(key.into()),cost_selected:Some(vec![cost]),target_id:(key==MARK).then_some(target.clone()),..Action::new("activate")});for _ in 0..40{if let Some(p)=t.room.game.pending.clone(){let ids=if p.choice.kind=="wm063-player"{vec!["p0".into()]}else{p.choice.options.iter().take(p.choice.min.unwrap()).map(|o|o.id.clone()).collect()};t.choose(ids);}else if t.room.game.stack.is_empty(){break;}else{t.pass();}}assert!(t.room.game.stack.is_empty()&&t.room.game.pending.is_none());if key==REPRESS{assert_eq!(t.room.game.regions[0].influence[team],1);}if key==MARK{assert_eq!(t.room.game.board(&target).unwrap().1.permanent_combat_markers,1);}duplicates(t.value())}
fn constructed(seed:u64)->(Game,crate::deck::DeckDraft){use crate::{catalog,deck};let mut d=deck::preset("watchers").unwrap();d.id="closed-wm063".into();d.society_id=None;d.core_card_id=None;d.cards=[("WM063",3),("WM057",3),("JC102",3),("JC125",41)].into_iter().map(|(id,count)|catalog::DeckEntry{card_id:id.into(),count}).collect();assert!(deck::validate(d.clone()).is_err());let mut cards=catalog::catalog().cards.clone();cards.iter_mut().find(|c|c.id==ID).unwrap().supported=true;let d=deck::validate_with_registry(d,&cards,&catalog::catalog().societies).unwrap();let mut other=deck::preset("watchers").unwrap();other.society_id=None;other.core_card_id=None;other.cards=vec![catalog::DeckEntry{card_id:"JC125".into(),count:50}];let other=deck::validate(other).unwrap();let mut g=Game::new("wm063-natural".into(),"LOCAL".into(),"teams".into(),"P0".into(),"watchers".into(),seed).unwrap();for s in 1..4{g.join(format!("P{s}"),"watchers".into()).unwrap();}g.start_validated_decks(vec![d.clone(),other.clone(),other.clone(),other]).unwrap();g.drive().unwrap();(g,d)}
fn natural()->serde_json::Value{use crate::abi112_review_play_tests::Trace;let(seed,g,d)=(1..1025).find_map(|seed|{let(g,d)=constructed(seed);let h=&g.players[0].hand;(h.iter().any(|c|c.definition==ID)&&h.iter().any(|c|c.definition=="WM057")&&h.iter().any(|c|c.definition=="JC102")).then_some((seed,g,d))}).unwrap();let mut t=Trace::new_preserving_rng(g,"wm063-natural-attachment-and-draw".into(),6399);let mut done=false;for _ in 0..600{if let Some(p)=t.room.game.pending.clone(){t.choose(p.choice.options.iter().take(p.choice.min.unwrap_or(0)).map(|o|o.id.clone()).collect());continue;}if done&&t.room.game.stack.is_empty()&&t.room.game.effects.is_empty(){break;}let g=&t.room.game;let legal=g.legal_actions(0);let pick=legal.iter().find(|a|a.action.ability_id.as_deref()==Some(DRAW)).or_else(||legal.iter().find(|a|a.action.kind=="play"&&a.action.card_id.as_ref().is_some_and(|id|g.players[0].hand.iter().any(|c|c.id==*id&&c.definition==ID)))).or_else(||if g.players[0].assets.len()<2{legal.iter().find(|a|a.action.kind=="asset"&&a.action.card_id.as_ref().is_some_and(|id|g.players[0].hand.iter().any(|c|c.id==*id&&matches!(c.definition.as_str(),"WM057"|"JC125"))))}else{None});if let Some(a)=pick{if a.action.ability_id.as_deref()==Some(DRAW){done=true;}t.action(0,a.action.clone());}else{t.pass();}}assert!(done&&t.room.game.stack.is_empty());assert!(t.room.game.attachments.iter().any(|a|a.card.definition==ID));let mut v=t.value();v["construction"]=serde_json::json!({"deck":d,"seed":seed,"ordinaryCards":50,"privateRegistryOnly":true,"noLayoutOrResourceMutation":true});duplicates(v)}
#[test]fn wm063_native_room_export(){use sha2::{Digest,Sha256};let cases=vec![natural(),prepared(DRAW,6301),prepared(REPRESS,6302),prepared(MARK,6303)];let mut b=crate::shoggoth_tests::shoggoth_source_bindings();for(n,bytes)in[("rust-game/src/wm063.rs",include_bytes!("wm063.rs").as_slice()),("rust-game/src/wm063_tests.rs",include_bytes!("wm063_tests.rs").as_slice())]{b["files"].as_object_mut().unwrap().insert(n.into(),serde_json::json!(format!("{:x}",Sha256::digest(bytes))));}if let Ok(path)=std::env::var("WM063_NATIVE_OUT"){std::fs::write(path,serde_json::to_vec_pretty(&serde_json::json!({"catalog":crate::catalog::catalog(),"sourceBindings":b,"cases":cases})).unwrap()).unwrap();}}
